-- Lote final da coletânea: questões projetadas, residência e tópicos
-- cirúrgicos. Formulações sem alternativa válida foram tornadas unívocas.
BEGIN;
CREATE OR REPLACE FUNCTION pg_temp.gastro_mon3_uuid(seed text) RETURNS uuid
LANGUAGE sql IMMUTABLE AS $$
  SELECT (substr(md5(seed),1,8)||'-'||substr(md5(seed),9,4)||'-5'||substr(md5(seed),14,3)||'-a'||substr(md5(seed),18,3)||'-'||substr(md5(seed),21,12))::uuid
$$;
DO $$
DECLARE v_discipline_id uuid; v_topic_id uuid; v_question_id uuid; q record; a jsonb;
BEGIN
  SELECT id INTO v_discipline_id FROM public.disciplines WHERE slug='gastroenterologia' LIMIT 1;
  IF v_discipline_id IS NULL THEN RAISE EXCEPTION 'Disciplina Gastroenterologia não encontrada'; END IF;
  FOR q IN SELECT * FROM jsonb_to_recordset($data$[
    {"k":"mon-anal-tumor-local","topic":"Doenças anorretais","d":"difícil","type":"single","s":"Homem de 78 anos, alto risco cirúrgico, apresenta pequeno tumor superficial da margem anal, lateral e sem evidência de invasão esfincteriana ou linfonodal. Qual tratamento local pode ser considerado?","c":["C"],"g":"Lesões pequenas e superficiais da margem anal, bem diferenciadas e sem invasão esfincteriana podem ser tratadas por excisão local com margens adequadas.","sum":"Margem anal pequena e superficial pode permitir excisão local.","mem":"Superficial e lateral: preserve o esfíncter quando oncologicamente seguro.","trap":"Tumores do canal anal geralmente seguem estratégia de quimiorradioterapia, diferente da margem cutânea selecionada.","alts":[["A","Radioterapia isolada obrigatória","Incorreta. Não é a única opção para lesão superficial selecionada."],["B","Quimioterapia isolada","Incorreta. Não controla adequadamente uma lesão localizada."],["C","Excisão local com margens adequadas","Correta. Pode preservar função em paciente selecionado."],["D","Amputação abdominoperineal obrigatória","Incorreta. É excessiva para a descrição."],["E","Nenhum tratamento pelo risco cirúrgico","Incorreta. Procedimento local pode ser viável."]]},
    {"k":"mon-diverticulite-clinica","topic":"Doença diverticular","d":"médio","type":"single","s":"Sobre o tratamento clínico da diverticulite aguda não complicada, assinale a alternativa incorreta.","c":["A"],"g":"Na fase aguda, a dieta é individualizada e pode ser líquida/leve conforme tolerância; dieta rica em resíduos não é imposta durante dor e inflamação.","sum":"Fase aguda não é momento de forçar resíduos.","mem":"Inflamou: alivie; recuperou: fibra pode voltar.","trap":"Antibiótico não é obrigatório em todo imunocompetente com quadro leve não complicado.","alts":[["A","Dieta laxativa rica em resíduos deve ser iniciada obrigatoriamente durante a crise","Correta como incorreta. Pode piorar sintomas e não é recomendação universal."],["B","Sonda nasogástrica geralmente não é necessária","Incorreta como resposta. É verdadeira."],["C","Casos leves selecionados podem ser tratados ambulatorialmente","Incorreta como resposta. É verdadeira."],["D","Quadros graves exigem cobertura para gram-negativos e anaeróbios","Incorreta como resposta. É verdadeira."],["E","Febre persistente sugere abscesso ou outra complicação","Incorreta como resposta. É verdadeira."]]},
    {"k":"mon-hemorroida-nao-complicada","topic":"Doenças anorretais","d":"fácil","type":"single","s":"Qual achado é menos compatível com doença hemorroidária interna não complicada?","c":["A"],"g":"Hemorroidas internas tipicamente causam sangramento vermelho vivo e prolapso; dor importante sugere trombose externa, estrangulamento ou outro diagnóstico.","sum":"Hemorroida interna sangra e prolapsa, mas geralmente não dói.","mem":"Acima da linha pectínea: pouca dor somática.","trap":"Dor anal intensa pede procura de fissura, abscesso ou trombose.","alts":[["A","Dor anorretal intensa e contínua","Correta. Não é típica da forma interna não complicada."],["B","Irritação ou prurido por prolapso/umidade","Incorreta como resposta. Pode ocorrer."],["C","Sangramento vermelho vivo","Incorreta como resposta. É manifestação comum."],["D","Prolapso durante evacuação","Incorreta como resposta. Define graus mais avançados."],["E","Sensação de umidade anal","Incorreta como resposta. Pode acompanhar prolapso."]]},
    {"k":"mon-lynch-incorreta","topic":"Câncer colorretal","d":"médio","type":"single","s":"Qual afirmação sobre síndrome de Lynch não corresponde à verdade?","c":["C"],"g":"Lynch é mais comum que PAF entre as síndromes hereditárias de câncer colorretal e associa tumores precoces, proximais, sincrônicos/metacrônicos e câncer endometrial.","sum":"Lynch: mais comum que PAF, proximal e endométrio.","mem":"Sem pólipos numerosos não significa síndrome rara.","trap":"PAF tem penetrância extrema, mas é menos prevalente.","alts":[["A","Pode causar câncer em idade precoce","Incorreta como resposta. É verdadeiro."],["B","Há predomínio de tumores do cólon direito","Incorreta como resposta. É verdadeiro."],["C","Sua prevalência é menor que a da PAF","Correta como falsa. Lynch é mais prevalente."],["D","Há predisposição a câncer de endométrio","Incorreta como resposta. É verdadeiro."],["E","Tumores sincrônicos e metacrônicos são mais frequentes","Incorreta como resposta. É verdadeiro."]]},
    {"k":"mon-sii-caso-exames","topic":"Síndrome do intestino irritável","d":"médio","type":"single","s":"Mulher de 35 anos apresenta dor, borborigmos e fezes aquosas desencadeadas por alimentos e estresse, sem febre, anemia, perda ponderal ou alterações fecais. Qual abordagem é mais apropriada?","c":["B"],"g":"O quadro favorece SII-D; recomenda-se diagnóstico positivo, investigação limitada guiada por subtipo e ausência de colonoscopia rotineira sem alarme.","sum":"SII típica pede poucos exames, não exclusão infinita.","mem":"Sem alarme, investigue com parcimônia.","trap":"Na forma diarreica, sorologia celíaca e calprotectina podem ser úteis conforme contexto.","alts":[["A","Laparotomia exploradora","Incorreta. Não há abdome agudo."],["B","Diagnóstico positivo de SII, com hemograma e avaliação seletiva para doença celíaca/inflamação conforme contexto","Correta. Evita exames invasivos desnecessários."],["C","Colonoscopia urgente obrigatória","Incorreta. Não há alarme ou indicação etária descrita."],["D","Antibiótico empírico prolongado","Incorreta. Não há evidência de infecção."],["E","Dieta sem glúten vitalícia sem confirmação","Incorreta. Não se diagnostica doença celíaca assim."]]},
    {"k":"mon-pancreatica-disabsorcao-vf","topic":"Pancreatite crônica","d":"difícil","type":"true_false","s":"Paciente etilista apresenta diarreia volumosa, fezes flutuantes e perda ponderal. Julgue as afirmações sobre insuficiência pancreática exócrina.","c":["A:F","B:F","C:V","D:F","E:F"],"g":"Esteatorreia pancreática melhora com jejum por componente osmótico, D-xilose tende a ser normal e a reposição deve fornecer lipase suficiente.","sum":"D-xilose normal + gordura alta aponta má digestão pancreática.","mem":"Pâncreas: xilose normal, lipase baixa.","trap":"Diabetes tipo 3c pode ser lábil por deficiência simultânea de insulina e glucagon.","alts":[["A","A diarreia decorre de estimulação osmótica direta do álcool pela aldeído-desidrogenase.","Falsa. O quadro sugere má digestão por insuficiência exócrina."],["B","Melhora noturna em jejum define diarreia funcional.","Falsa. Também ocorre em diarreia osmótica por má digestão/má absorção."],["C","D-xilose normal com gordura fecal de 14 g/24 h favorece causa extramucosa, como insuficiência pancreática.","Verdadeira. A mucosa absorve xilose, mas falta digestão de gorduras."],["D","Diabetes pancreatogênico é raro e sempre fácil de controlar com sulfonilureia.","Falsa. Pode ser frequente e lábil, com risco de hipoglicemia."],["E","Reposição enzimática deve priorizar cápsulas com maior teor de amilase para controlar esteatorreia.","Falsa. A dose é guiada principalmente pela quantidade de lipase."]]},
    {"k":"mon-iep-achados","topic":"Pancreatite crônica","d":"médio","type":"multiple","s":"Quais achados são compatíveis com insuficiência pancreática avançada? Selecione todas as corretas.","c":["B","D","E"],"g":"Esteatorreia, diabetes por comprometimento endócrino e hipocalcemia/deficiência de vitamina D podem ocorrer; D-xilose costuma permanecer normal.","sum":"IEP dá gordura nas fezes, deficiência vitamínica e pode coexistir com diabetes.","mem":"Exócrino perde lipase; endócrino perde insulina.","trap":"Supercrescimento bacteriano pode coexistir, mas não é consequência obrigatória direta.","alts":[["A","Teste de D-xilose reduzido por falha pancreática isolada","Incorreta. A absorção de xilose independe do pâncreas."],["B","Esteatorreia com gordura fecal aumentada","Correta. É manifestação de má digestão lipídica."],["C","Supercrescimento bacteriano obrigatório","Incorreta. Não é achado necessário."],["D","Hiperglicemia por diabetes pancreatogênico","Correta. Pode coexistir em doença avançada."],["E","Hipocalcemia ou osteopenia associada a deficiência de vitamina D","Correta. Má absorção de vitamina D contribui."]]},
    {"k":"mon-diverticulite-hartmann","topic":"Doença diverticular","d":"difícil","type":"single","s":"Paciente com diverticulite sigmoide perfurada, peritonite difusa purulenta e choque séptico refratário apresenta extrema instabilidade. Entre as opções, qual operação de controle de foco é mais apropriada?","c":["B"],"g":"Em paciente instável com peritonite generalizada, ressecção do sigmoide sem anastomose e colostomia terminal (Hartmann) é opção segura de controle de danos.","sum":"Instável e contaminado: evite anastomose primária.","mem":"Choque + peritonite = Hartmann entre as opções.","trap":"Em pacientes estáveis, ressecção com anastomose e ileostomia pode ser considerada.","alts":[["A","Colectomia total de rotina","Incorreta. Extensão excessiva sem indicação adicional."],["B","Sigmoidectomia com colostomia terminal e fechamento do coto retal","Correta. É a cirurgia de Hartmann."],["C","Apenas drenagem percutânea","Incorreta. Peritonite difusa requer cirurgia."],["D","Somente antibiótico e hidratação","Incorreta. Falta controle de foco."],["E","Anastomose primária sem proteção em choque refratário","Incorreta. Risco de deiscência é elevado."]]},
    {"k":"mon-diverticulite-tc","topic":"Doença diverticular","d":"fácil","type":"single","s":"Qual exame é considerado método de escolha para diagnóstico e avaliação de complicações da diverticulite aguda?","c":["D"],"g":"TC de abdome e pelve com contraste define inflamação, abscesso, ar extraluminal, fístula e obstrução.","sum":"Diverticulite aguda se mapeia com TC.","mem":"Divertículo inflamado: tomografia.","trap":"Colonoscopia é realizada após resolução quando indicada, não na fase aguda.","alts":[["A","Radiografia de tórax isolada","Incorreta. Pode mostrar ar livre, mas não avalia adequadamente a diverticulite."],["B","Ressonância como única opção padrão","Incorreta. Pode ser alternativa, mas não é primeira escolha usual."],["C","Colonoscopia durante a crise","Incorreta. Aumenta risco e não estagia inflamação pericólica."],["D","Tomografia de abdome e pelve","Correta. Tem alta acurácia e classifica complicações."],["E","Enema opaco na fase aguda","Incorreta. É evitado."]]},
    {"k":"mon-pneumoperitonio-cirurgia","topic":"Abdome agudo","d":"médio","type":"single","s":"Paciente de 67 anos apresenta dor súbita, febre, irritação peritoneal difusa e pneumoperitônio na radiografia. Qual conduta é prioritária?","c":["A"],"g":"Perfuração de víscera oca com peritonite exige ressuscitação, antibióticos e controle cirúrgico urgente do foco.","sum":"Ar livre + peritonite = cirurgia urgente.","mem":"Pneumoperitônio com rigidez não espera.","trap":"TC não deve atrasar operação quando diagnóstico e indicação já estão claros.","alts":[["A","Ressuscitação e procedimento cirúrgico imediato","Correta. Há perfuração com peritonite."],["B","Contraindicar videolaparoscopia em todos os casos","Incorreta. A via depende de estabilidade e experiência."],["C","Aguardar TC obrigatoriamente antes de chamar cirurgia","Incorreta. Pode atrasar controle de foco."],["D","Tratar como dor visceral sem componente somático","Incorreta. Irritação peritoneal indica dor somática."],["E","Alta com analgesia","Incorreta. É emergência."]]},
    {"k":"mon-alca-fechada","topic":"Abdome agudo","d":"difícil","type":"single","s":"Na obstrução intestinal em alça fechada, qual é a principal preocupação clínica?","c":["C"],"g":"A alça ocluída em dois pontos distende rapidamente, compromete retorno venoso e fluxo arterial, podendo evoluir para estrangulamento, necrose e perfuração.","sum":"Alça fechada estrangula.","mem":"Fechou dos dois lados, perde sangue no meio.","trap":"Desidratação importa, mas não é a complicação local mais temida.","alts":[["A","Somente desidratação","Incorreta. É repercussão sistêmica, mas não a maior ameaça específica."],["B","Apenas acidose metabólica","Incorreta. Pode surgir secundariamente à isquemia."],["C","Estrangulamento vascular com necrose e perfuração","Correta. Exige reconhecimento e cirurgia precoce."],["D","Intussuscepção obrigatória","Incorreta. É uma causa possível, não consequência universal."],["E","Hipertermia isolada","Incorreta. Não define a complicação principal."]]},
    {"k":"mon-linha-pectinea","topic":"Doenças anorretais","d":"fácil","type":"single","s":"Qual estrutura anatômica separa os plexos hemorroidários interno e externo e marca mudança importante de inervação?","c":["C"],"g":"A linha pectínea separa epitélio e drenagens distintas; abaixo dela há inervação somática sensível à dor.","sum":"Linha pectínea divide interno de externo.","mem":"Pectínea parte o plexo.","trap":"Essa diferença explica por que ligadura elástica externa seria dolorosa.","alts":[["A","Canal anal inteiro","Incorreta. É região, não a linha divisória."],["B","Junção retossigmoide","Incorreta. Está muito proximal."],["C","Linha pectínea","Correta. É o marco anatômico."],["D","Fossa isquiorretal","Incorreta. É espaço perianal."],["E","Feixe puborretal","Incorreta. Participa da continência, não separa plexos."]]},
    {"k":"res-pancreatite-lipase","topic":"Pancreatite aguda","d":"médio","type":"single","s":"Em relação à amilase e à lipase na pancreatite aguda, assinale a alternativa correta.","c":["C"],"g":"Lipase tem maior especificidade e permanece elevada por mais tempo, sendo mais sensível quando o paciente procura atendimento após 48 horas.","sum":"Chegou tarde: lipase ajuda mais.","mem":"Lipase lasts longer.","trap":"Insuficiência renal pode elevar ambas por menor depuração.","alts":[["A","Qualquer elevação de lipase confirma pancreatite","Incorreta. O critério usual é pelo menos três vezes o limite, no contexto adequado."],["B","Amilase é mais específica que lipase","Incorreta. Lipase é geralmente mais específica."],["C","Após 48 horas, lipase tende a ser mais sensível","Correta. Sua elevação persiste mais tempo."],["D","Função renal não interfere nas dosagens","Incorreta. Redução da depuração pode elevar enzimas."],["E","Amilase salivar e pancreática são a mesma isoenzima","Incorreta. Existem isoenzimas distintas."]]},
    {"k":"res-pancreatite-suporte","topic":"Pancreatite aguda","d":"médio","type":"single","s":"Homem com pancreatite aguda, hipotensão responsiva à reposição, creatinina elevada e sem peritonite está nas primeiras 48 horas. Qual conduta imediata é mais apropriada?","c":["E"],"g":"Tratamento inicial é suporte intensivo com fluidos guiados por resposta, analgesia, monitorização e alimentação enteral precoce conforme tolerância; não há indicação automática de antibiótico, TC ou cirurgia.","sum":"Primeiras horas: suporte, reavalie e alimente cedo quando possível.","mem":"Pancreatite começa na UTI, não no centro cirúrgico.","trap":"TC contrastada precoce pode ser inadequada em lesão renal e não muda conduta quando diagnóstico é claro.","alts":[["A","TC contrastada imediata obrigatória","Incorreta. Pode ser adiada e há disfunção renal."],["B","Antibiótico empírico","Incorreta. Não há infecção documentada."],["C","Laparotomia e desbridamento","Incorreta. Não há indicação."],["D","Drenagem percutânea imediata","Incorreta. Não há coleção infectada descrita."],["E","Analgesia, reposição guiada, monitorização intensiva e nutrição enteral conforme tolerância","Correta. É o tratamento inicial."]]},
    {"k":"res-pancreas-rastreio","topic":"Câncer de pâncreas","d":"médio","type":"single","s":"Sobre rastreamento de câncer pancreático, assinale a alternativa correta.","c":["B"],"g":"Não se recomenda rastrear população geral assintomática; vigilância com RM/CPRM e/ou ecoendoscopia é reservada a grupos hereditários de alto risco.","sum":"População geral não rastreia; alto risco genético vigia.","mem":"CA 19-9 não é mamografia do pâncreas.","trap":"Diabetes novo após 50 anos merece avaliação clínica, mas não gera programa universal isoladamente.","alts":[["A","Todo diabético acima de 50 anos deve fazer imagem anual","Incorreta. Não é recomendação universal."],["B","Não há rastreamento recomendado para população geral assintomática","Correta. Benefício não foi demonstrado."],["C","CA 19-9 anual deve começar aos 50 anos","Incorreta. Não serve como teste de rastreio."],["D","Toda pessoa com síndrome de Lynch segue o mesmo protocolo independentemente da história familiar","Incorreta. Vigilância pancreática é individualizada conforme risco e diretriz."],["E","Ultrassom abdominal anual reduz mortalidade populacional","Incorreta. Não há evidência para essa estratégia."]]},
    {"k":"res-pancreas-clinica","topic":"Câncer de pâncreas","d":"difícil","type":"single","s":"Sobre adenocarcinoma pancreático, assinale a alternativa correta.","c":["E"],"g":"Ressecção é a única possibilidade de cura, mas recorrência é frequente; sobrevida depende de estágio, margens, linfonodos e terapia sistêmica.","sum":"Poucos são ressecáveis; mesmo após cirurgia, risco de recidiva é alto.","mem":"Ressecou, pode curar, mas precisa terapia sistêmica.","trap":"Courvoisier é vesícula palpável e indolor; CA 19-9 auxilia acompanhamento, não confirma sozinho.","alts":[["A","Courvoisier é vesícula palpável e dolorosa","Incorreta. É classicamente indolor."],["B","Icterícia é o achado mais comum em tumores de qualquer localização pancreática","Incorreta. Depende da localização; dor e perda de peso são frequentes."],["C","CEA é marcador específico diagnóstico","Incorreta. Nenhum marcador confirma isoladamente."],["D","Todo tumor T3N0M0 é irressecável","Incorreta. Ressecabilidade depende sobretudo do envolvimento vascular/metastático."],["E","Ressecção oferece possibilidade de cura, mas apenas em minoria e com risco relevante de recorrência","Correta. Resume o prognóstico real."]]},
    {"k":"res-sibo-exceto","topic":"Síndromes disabsortivas","d":"médio","type":"single","s":"Qual condição não é causa típica de supercrescimento bacteriano do intestino delgado?","c":["D"],"g":"SIBO decorre de hipocloridria, dismotilidade ou alterações anatômicas; colite pseudomembranosa é infecção colônica por C. difficile.","sum":"SIBO precisa de estase, pouca acidez ou atalho anatômico.","mem":"Pseudomembrana fica no cólon.","trap":"Diabetes e esclerodermia causam dismotilidade e podem predispor.","alts":[["A","Esclerose sistêmica","Incorreta como resposta. Dismotilidade predispõe."],["B","Acloridria ou supressão ácida","Incorreta como resposta. Pode favorecer colonização."],["C","Fístula enterocolônica em Crohn","Incorreta como resposta. Alteração anatômica predispõe."],["D","Colite pseudomembranosa por C. difficile","Correta como exceção. É doença colônica distinta."],["E","Diabetes com neuropatia autonômica","Incorreta como resposta. Dismotilidade pode predispor."]]},
    {"k":"res-malabsorcao-testes","topic":"Síndromes disabsortivas","d":"médio","type":"single","s":"Em relação aos testes de má absorção, assinale a alternativa incorreta.","c":["E"],"g":"Teste de secretina avalia função exócrina pancreática, não função gástrica; gordura fecal, Sudan, D-xilose e teste respiratório têm finalidades específicas.","sum":"Secretina testa pâncreas.","mem":"Secretina chama bicarbonato pancreático.","trap":"Gordura fecal quantitativa é referência histórica, mas trabalhosa.","alts":[["A","Gordura fecal quantitativa é método de referência para esteatorreia","Incorreta como resposta. É verdadeiro."],["B","Sudan pesquisa qualitativamente gordura fecal","Incorreta como resposta. É verdadeiro."],["C","D-xilose diferencia doença mucosa de insuficiência pancreática","Incorreta como resposta. É o uso histórico."],["D","Hidrogênio expirado auxilia no diagnóstico de má absorção de lactose","Incorreta como resposta. É verdadeiro."],["E","Estimulação com secretina é padrão-ouro da função gástrica","Correta como incorreta. Avalia secreção pancreática."]]},
    {"k":"res-sii-d-tratamento","topic":"Síndrome do intestino irritável","d":"médio","type":"single","s":"Qual conjunto é coerente para tratamento individualizado da SII com predomínio de diarreia e dor?","c":["A"],"g":"Loperamida melhora frequência/consistência, antiespasmódico pode aliviar dor e tricíclico em baixa dose pode modular dor e desacelerar trânsito.","sum":"SII-D: segure trânsito e module dor.","mem":"D: loperamida; dor: antiespasmódico/TCA.","trap":"Loperamida não melhora necessariamente sintomas globais e deve ser individualizada.","alts":[["A","Loperamida, antiespasmódico e antidepressivo tricíclico em pacientes selecionados","Correta. Cada agente trata componente relevante."],["B","Fibra, tegaserode e tricíclico como esquema padrão","Incorreta. Tegaserode não é terapia de SII-D."],["C","Antiespasmódico, fibra e SSRI obrigatoriamente","Incorreta. Pode piorar diarreia e não é esquema padrão universal."],["D","Metronidazol e tegaserode","Incorreta. Não há indicação rotineira."],["E","Opioide forte crônico","Incorreta. Risco supera benefício."]]},
    {"k":"res-rcu-cirurgia-exceto","topic":"Retocolite ulcerativa","d":"médio","type":"single","s":"São indicações clássicas de cirurgia na retocolite ulcerativa, exceto:","c":["A"],"g":"Displasia/câncer, hemorragia maciça, megacólon tóxico, perfuração e doença intratável indicam cirurgia; manifestações extraintestinais isoladas não são indicação geral.","sum":"Opere complicação, câncer ou refratariedade.","mem":"Sangra, dilata, perfura, displasia ou não controla.","trap":"Algumas manifestações, como pioderma, podem não melhorar e até piorar após cirurgia.","alts":[["A","Manifestações extraintestinais isoladas, de modo geral","Correta como exceção. Não constituem indicação universal."],["B","Displasia de alto grau ou câncer","Incorreta como resposta. É indicação."],["C","Doença clinicamente intratável","Incorreta como resposta. É indicação."],["D","Hemorragia colônica intensa não controlada","Incorreta como resposta. É indicação urgente."],["E","Megacólon tóxico refratário ou complicado","Incorreta como resposta. É indicação."]]},
    {"k":"res-crohn-prognostico","topic":"Doença de Crohn","d":"médio","type":"single","s":"Qual conjunto contém fatores associados a curso mais grave da doença de Crohn?","c":["D"],"g":"Tabagismo, doença perianal/penetrante, necessidade precoce de corticoide, idade jovem e extensão aumentam risco de evolução complicada.","sum":"Perianal, penetrante, fumante e esteroide precoce preocupam.","mem":"Fístula + fumo = mau rumo.","trap":"Apendicectomia prévia e etilismo não são os marcadores centrais usados para estratificação.","alts":[["A","Apendicectomia prévia isolada e doença extensa","Incorreta. Apendicectomia não é marcador central."],["B","Idade avançada isolada e manifestações extraintestinais","Incorreta. Não é o melhor conjunto."],["C","História familiar e longa duração apenas","Incorreta. São insuficientes."],["D","Doença perianal, tabagismo e necessidade de corticoide sistêmico","Correta. Associam-se a curso mais complicado."],["E","Etilismo e idade avançada","Incorreta. Não é a combinação reconhecida."]]},
    {"k":"res-brida-operacao","topic":"Abdome agudo","d":"difícil","type":"single","s":"Homem com múltiplas cirurgias abdominais apresenta obstrução intestinal, hipotensão, febre, leucocitose, disfunção renal e peritonite difusa. Qual hipótese e tratamento são mais prováveis?","c":["D"],"g":"Aderências são causa comum de obstrução de delgado após cirurgia; instabilidade e peritonite indicam estrangulamento/perfuração e exigem operação.","sum":"Brida simples observa; brida com peritonite opera.","mem":"Cicatriz + obstrução = brida; choque = laparotomia.","trap":"Tratamento conservador só cabe sem sinais de isquemia ou peritonite.","alts":[["A","Volvo de sigmoide sem investigação","Incorreta. Histórico cirúrgico favorece brida."],["B","Obstrução por brida com tratamento clínico exclusivo","Incorreta. Peritonite contraindica manejo conservador."],["C","Neoplasia de reto e colonoscopia urgente","Incorreta. Colonoscopia não é apropriada com peritonite."],["D","Obstrução de delgado por brida com exploração cirúrgica urgente","Correta. Há sinais de complicação."],["E","Colecistite e colecistectomia","Incorreta. Não explica obstipação e distensão."]]},
    {"k":"res-reto-estadiamento-local","topic":"Câncer colorretal","d":"médio","type":"single","s":"Qual exame é central para o estadiamento local de uma neoplasia de reto após confirmação histológica?","c":["B"],"g":"RM de pelve avalia profundidade, fáscia mesorretal, linfonodos e relação com esfíncteres; TC de tórax/abdome avalia doença à distância e CEA fornece linha basal.","sum":"Reto local = RM pélvica; distante = TC.","mem":"R de reto, R de ressonância.","trap":"A questão antiga perguntava qual exame não fazia parte, mas todas as opções integravam a avaliação.","alts":[["A","TC de tórax","Incorreta. É importante para metástases pulmonares, não é o melhor exame local."],["B","Ressonância magnética da pelve","Correta. É o principal método de estadiamento local."],["C","CEA sérico","Incorreta. É marcador basal/prognóstico, não imagem local."],["D","TC de abdome","Incorreta. Avalia principalmente metástases."],["E","Hemograma","Incorreta. Avalia repercussão, não estágio local."]]},
    {"k":"res-diverticulo-pseudo","topic":"Doença diverticular","d":"fácil","type":"single","s":"Em relação à doença diverticular dos cólons, assinale a alternativa incorreta.","c":["C"],"g":"Pseudodivertículos adquiridos contêm mucosa e submucosa herniadas através da muscular, não todas as camadas da parede.","sum":"Pseudodivertículo não tem parede completa.","mem":"Pseudo perde a muscular própria.","trap":"Divertículo verdadeiro inclui todas as camadas.","alts":[["A","Divertículos relacionam-se a alterações estruturais, motilidade e pressão segmentar","Incorreta como resposta. É verdadeiro."],["B","Surgem em pontos de penetração das vasa recta","Incorreta como resposta. É verdadeiro."],["C","Pseudodivertículo contém todas as camadas do cólon","Correta como incorreta. Contém principalmente mucosa e submucosa."],["D","Sigmoide e descendente são locais frequentes no padrão ocidental","Incorreta como resposta. É verdadeiro."],["E","Prevalência aumenta com idade","Incorreta como resposta. É verdadeiro."]]},
    {"k":"res-diverticular-complicacao","topic":"Doença diverticular","d":"fácil","type":"single","s":"Qual opção não integra as principais complicações da doença diverticular?","c":["E"],"g":"Complicações incluem diverticulite, perfuração, abscesso, peritonite, fístula, estenose/obstrução e hemorragia; fecaloma não é complicação principal específica.","sum":"Divertículo inflama, sangra, perfura, fistuliza ou obstrui.","mem":"Fecaloma é constipação, não complicação diverticular típica.","trap":"Um fecalito pode obstruir o colo do divertículo, mas fecaloma não é desfecho principal da doença.","alts":[["A","Episódios de diverticulite","Incorreta como resposta. É complicação."],["B","Perfuração","Incorreta como resposta. É complicação."],["C","Hemorragia digestiva","Incorreta como resposta. É complicação."],["D","Abscesso e peritonite","Incorreta como resposta. São complicações."],["E","Formação de fecaloma","Correta como exceção. Não é complicação principal específica."]]},
    {"k":"res-psc-colectomia","topic":"Retocolite ulcerativa","d":"difícil","type":"single","s":"Sobre manifestações e cirurgia nas doenças inflamatórias intestinais, assinale a alternativa correta.","c":["D"],"g":"Colectomia trata a doença colônica da RCU, mas não interrompe de forma previsível a progressão da colangite esclerosante primária.","sum":"Tirar o cólon não cura a CEP.","mem":"CEP segue no fígado mesmo sem cólon.","trap":"Crohn é transmural e fistulizante; RCU é contínua e mucosa.","alts":[["A","RCU apresenta lesões salteadas do ceco ao reto","Incorreta. É contínua a partir do reto."],["B","Em pancolite, Crohn sempre tem maior risco de câncer que RCU no mesmo tempo","Incorreta. Risco depende de extensão e inflamação; a afirmação absoluta é falsa."],["C","Fístulas enteroentéricas são mais comuns na RCU","Incorreta. São típicas de Crohn transmural."],["D","Colectomia não altera necessariamente o curso da colangite esclerosante primária associada à RCU","Correta. A doença hepatobiliar pode progredir independentemente."],["E","Toda doença de Crohn limitada ao cólon é curada por proctocolectomia com bolsa ileal","Incorreta. Crohn pode recorrer e bolsa ileal não é opção padrão."]]}
  ]$data$::jsonb) AS x(k text,topic text,d text,type text,s text,c jsonb,g text,sum text,mem text,trap text,alts jsonb)
  LOOP
    SELECT id INTO v_topic_id FROM public.topics WHERE discipline_id=v_discipline_id AND name=q.topic LIMIT 1;
    IF v_topic_id IS NULL THEN v_topic_id:=pg_temp.gastro_mon3_uuid('gastro-topic-'||q.topic); INSERT INTO public.topics(id,discipline_id,name) VALUES(v_topic_id,v_discipline_id,q.topic) ON CONFLICT(id) DO UPDATE SET name=EXCLUDED.name; END IF;
    v_question_id:=pg_temp.gastro_mon3_uuid('gastro-p3-'||q.k);
    INSERT INTO public.questions(id,discipline_id,topic_id,exam,difficulty,statement,question_type,correct_answer,correct_answers,general_comment,summary,memory_tip,trap,reference,active,image_url)
    VALUES(v_question_id,v_discipline_id,v_topic_id,'P3',q.d,q.s,q.type,split_part(q.c->>0, ':', 1),ARRAY(SELECT jsonb_array_elements_text(q.c)),q.g,q.sum,q.mem,q.trap,'Prova 3 de Gastroenterologia — payload deduplicado e revisado em 2026.',true,NULL)
    ON CONFLICT(id) DO UPDATE SET topic_id=EXCLUDED.topic_id,exam='P3',difficulty=EXCLUDED.difficulty,statement=EXCLUDED.statement,question_type=EXCLUDED.question_type,correct_answer=EXCLUDED.correct_answer,correct_answers=EXCLUDED.correct_answers,general_comment=EXCLUDED.general_comment,summary=EXCLUDED.summary,memory_tip=EXCLUDED.memory_tip,trap=EXCLUDED.trap,reference=EXCLUDED.reference,active=true,image_url=NULL;
    DELETE FROM public.alternatives WHERE question_id=v_question_id;
    FOR a IN SELECT value FROM jsonb_array_elements(q.alts) LOOP INSERT INTO public.alternatives(id,question_id,letter,text,explanation) VALUES(pg_temp.gastro_mon3_uuid(v_question_id::text||(a->>0)),v_question_id,a->>0,a->>1,a->>2); END LOOP;
  END LOOP;
END $$;
DO $$
DECLARE v_count integer; v_blank integer;
BEGIN
  SELECT count(*) INTO v_count FROM public.questions WHERE id IN (SELECT pg_temp.gastro_mon3_uuid('gastro-p3-'||key) FROM unnest(ARRAY[
    'mon-anal-tumor-local','mon-diverticulite-clinica','mon-hemorroida-nao-complicada','mon-lynch-incorreta','mon-sii-caso-exames','mon-pancreatica-disabsorcao-vf','mon-iep-achados','mon-diverticulite-hartmann','mon-diverticulite-tc','mon-pneumoperitonio-cirurgia','mon-alca-fechada','mon-linha-pectinea','res-pancreatite-lipase','res-pancreatite-suporte','res-pancreas-rastreio','res-pancreas-clinica','res-sibo-exceto','res-malabsorcao-testes','res-sii-d-tratamento','res-rcu-cirurgia-exceto','res-crohn-prognostico','res-brida-operacao','res-reto-estadiamento-local','res-diverticulo-pseudo','res-diverticular-complicacao','res-psc-colectomia'
  ]) AS keys(key));
  SELECT count(*) INTO v_blank FROM public.alternatives a JOIN public.questions q ON q.id=a.question_id WHERE q.id IN (SELECT pg_temp.gastro_mon3_uuid('gastro-p3-'||key) FROM unnest(ARRAY[
    'mon-anal-tumor-local','mon-diverticulite-clinica','mon-hemorroida-nao-complicada','mon-lynch-incorreta','mon-sii-caso-exames','mon-pancreatica-disabsorcao-vf','mon-iep-achados','mon-diverticulite-hartmann','mon-diverticulite-tc','mon-pneumoperitonio-cirurgia','mon-alca-fechada','mon-linha-pectinea','res-pancreatite-lipase','res-pancreatite-suporte','res-pancreas-rastreio','res-pancreas-clinica','res-sibo-exceto','res-malabsorcao-testes','res-sii-d-tratamento','res-rcu-cirurgia-exceto','res-crohn-prognostico','res-brida-operacao','res-reto-estadiamento-local','res-diverticulo-pseudo','res-diverticular-complicacao','res-psc-colectomia'
  ]) AS keys(key)) AND (coalesce(trim(a.text),'')='' OR coalesce(trim(a.explanation),'')='');
  IF v_count<>26 OR v_blank<>0 THEN RAISE EXCEPTION 'Auditoria monitoria 3 falhou: questões=%, vazias=%',v_count,v_blank; END IF;
END $$;
COMMIT;
